function diffLines(aLines, bLines) {
  const added = []
  const removed = []
  const aSet = new Set(aLines)
  const bSet = new Set(bLines)

  for (const l of aLines) {
    if (!bSet.has(l)) removed.push(l)
  }
  for (const l of bLines) {
    if (!aSet.has(l)) added.push(l)
  }

  return { added, removed }
}
